Rust-ready emulation of glibc strtol(s, NULL, 10) in the default "C" locale:

    fn glibc_strtol_base10(bytes: &[u8]) -> i64 {
        let mut i = 0usize;
        // 1. skip leading whitespace: exactly isspace() in the C locale
        //    = b' ', 0x09 \t, 0x0a \n, 0x0b VT, 0x0c FF, 0x0d \r
        while i < bytes.len()
            && matches!(bytes[i], b' ' | 0x09 | 0x0a | 0x0b | 0x0c | 0x0d) { i += 1; }
        // 2. at most ONE optional sign, no space allowed after it
        let mut neg = false;
        if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') {
            neg = bytes[i] == b'-';
            i += 1;
        }
        // 3. longest run of ASCII digits b'0'..=b'9'
        //    (base 10: no 0x/0b prefix, no '_' separators, no thousands grouping,
        //     no non-ASCII digits)
        let start = i;
        let mut acc: u128 = 0;
        let mut overflow = false;
        let limit: u128 = if neg { 9223372036854775808u128 }   // |i64::MIN|
                          else   { 9223372036854775807u128 };  // i64::MAX
        while i < bytes.len() && bytes[i].is_ascii_digit() {
            let d = (bytes[i] - b'0') as u128;
            if !overflow {
                acc = acc * 10 + d;
                if acc > limit { overflow = true; }
            }
            i += 1;
        }
        // 4. no digits consumed at all -> 0 (errno EINVAL, value 0)
        if i == start { return 0; }
        // 5. out of long range -> SATURATE to LONG_MAX / LONG_MIN (errno ERANGE)
        if overflow { return if neg { i64::MIN } else { i64::MAX }; }
        // 6. in range
        if neg { (acc as i128).wrapping_neg() as i64 } else { acc as i64 }
        //   (acc == 2^63 with neg is exactly i64::MIN and is NOT overflow)
    }

    fn argv_to_num(arg_bytes: &[u8]) -> i32 {
        glibc_strtol_base10(arg_bytes) as i32   // `as i32` = wrapping truncation, mod 2^32
    }

