    pub fn truncate(word: &str, length: usize, omission: &str) -> Vec<u8> {
        let b = word.as_bytes();
        if length >= b.len() { return b.to_vec(); }
        // unsigned arithmetic, exactly as in C++:
        let mut keep = length.wrapping_sub(omission.len());
        if keep > b.len() { keep = b.len(); }   // std::string::substr clamps count
        let mut out = Vec::with_capacity(keep + omission.len());
        out.extend_from_slice(&b[..keep]);
        out.extend_from_slice(omission.as_bytes());
        out                                     // may be invalid UTF-8
    }
    // Driver calls: line 7 = truncate(word, 5, "..."), line 8 = truncate(word, 10, "~").
    // Library default omission is "...".

Because the result may be invalid UTF-8, model it as Vec<u8> and write it with
